var sourceTitle = Tama.Args.Get(args, "source", "");
var targetTitle = Tama.Args.Get(args, "target", "");
var schemeName = Tama.Args.Get(args, "scheme", "");
var pid = new ElementId(Tama.Args.Get(args, "paramId", -1010106));
Document source = null, target = null;
foreach (Document d in app.Documents) { if (d.IsLinked) continue; if (d.Title == sourceTitle) source = d; if (d.Title == targetTitle) target = d; }
if (source == null || target == null) throw new Exception("Source or target not open");
Func<Element, Parameter> getP = e => e.Parameters.Cast<Parameter>().FirstOrDefault(p => p.Id == pid);
Func<Document, List<Autodesk.Revit.DB.Area>> areas = d => new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_Areas).WhereElementIsNotElementType().Cast<Autodesk.Revit.DB.Area>().Where(a => a.AreaScheme != null && a.AreaScheme.Name == schemeName).ToList();
string pName = null;
var valMap = areas(source).Select(a => { var p = getP(a); if (p != null) pName = p.Definition.Name; return new { k = (a.Level?.Name ?? "") + "|" + a.get_Parameter(BuiltInParameter.ROOM_NAME).AsString(), v = p?.AsString() }; })
  .Where(x => !string.IsNullOrEmpty(x.v)).GroupBy(x => x.k)
  .ToDictionary(g => g.Key, g => g.GroupBy(x => x.v).OrderByDescending(h => h.Count()).First().Key);
int set = 0, skippedOwned = 0, unchanged = 0; var missing = new HashSet<string>();
using (var t = new Transaction(target, "Copy area parameter")) {
  t.Start();
  foreach (var a in areas(target)) {
    if (WorksharingUtils.GetCheckoutStatus(target, a.Id) == CheckoutStatus.OwnedByOtherUser) { skippedOwned++; continue; }
    var key = (a.Level?.Name ?? "") + "|" + a.get_Parameter(BuiltInParameter.ROOM_NAME).AsString();
    if (!valMap.ContainsKey(key)) { missing.Add(key); continue; }
    var p = getP(a);
    if (p == null || p.IsReadOnly) { missing.Add(key + " (param n/a)"); continue; }
    if (p.AsString() == valMap[key]) { unchanged++; continue; }
    p.Set(valMap[key]); set++;
  }
  t.Commit();
}
return new { parameter = pName, set, unchanged, skippedOwned, missing, values = valMap.Values.Distinct() };
